texts = {}
for path, old, new, label in replacements:
    p = Path(path)
    if not p.exists():
        raise SystemExit(f'Missing {path}. No files were changed.')
    if path not in texts:
        texts[path] = p.read_text(encoding='utf-8')
    if old not in texts[path]:
        raise SystemExit(f'Could not find {label} in {path}. No files were changed.')
    texts[path] = texts[path].replace(old, new, 1)

new_component_path = Path('components/world/image-preview-button.tsx')
if new_component_path.exists():
    raise SystemExit('components/world/image-preview-button.tsx already exists. No files were changed.')
new_component = base64.b64decode('').decode('utf-8')

css_path = Path('components/sepulchria/sep-ui-unified.css')
if not css_path.exists():
    raise SystemExit('Missing unified CSS. No files were changed.')
css = css_path.read_text(encoding='utf-8')
css_append = '\n\n/* ==================================================================\n   PRECISE MESSAGE VISUAL OVERRIDES\n   ================================================================== */\n\n/*\n * OFF-GAME is deliberately much darker than ON-GAME.\n * This uses the existing skin surface mixed toward black; it introduces\n * no new hue. ID specificity intentionally beats the portal-wide unified\n * button selector.\n */\nbody.portal-skin-scope\n  #sep-offgame-message-selector {\n  background-color:\n    color-mix(\n      in srgb,\n      rgb(var(--sep-colour-100c09)) 28%,\n      black\n    ) !important;\n}\n\nbody.portal-skin-scope\n  #sep-offgame-message-selector:hover:not(:disabled) {\n  background-color:\n    color-mix(\n      in srgb,\n      rgb(var(--sep-colour-100c09)) 38%,\n      black\n    ) !important;\n}\n'
css_marker = 'PRECISE MESSAGE VISUAL OVERRIDES'
if css_marker not in css:
    css += css_append

# All validation is complete. Write only now.
for path, text in texts.items():
    Path(path).write_text(text, encoding='utf-8')
new_component_path.write_text(new_component, encoding='utf-8')
css_path.write_text(css, encoding='utf-8')

